prompt:
You are the Tester agent. The Developer produced these files for
task TASK-003 (Add quick-link tiles for existing services):

--- index.html ---
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>MapleSure SponsorConnect</title>
    <style>
        body {
            font-family: Arial, sans-serif;
            margin: 0;
            padding: 0;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }
        .container {
            width: 80%;
            max-width: 600px;
            padding: 20px;
            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
        }
        .tile-container {
            display: flex;
            justify-content: space-between;
            margin-bottom: 20px;
        }
        .tile {
            background-color: #0073e6;
            color: white;
            padding: 15px;
            text-align: center;
            border-radius: 5px;
            cursor: pointer;
            width: 30%;
        }
        .hidden {
            display: none;
        }
        footer {
            margin-top: 20px;
            font-size: 12px;
            color: #777;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="tile-container">
            <div class="tile" onclick="requireSignIn('policy-lookup')">Policy Lookup</div>
            <div class="tile" onclick="requireSignIn('claim-status')">Claim Status</div>
            <div class="tile" onclick="requireSignIn('commission-statement')">Commission Statement</div>
        </div>
        <form id="claim-form">
            <h3>Disability Claim Submission</h3>
            <label for="policy-number">Policy Number:</label><br>
            <input type="text" id="policy-number" name="policy-number"><br>
            <label for="member-id">Member ID:</label><br>
            <input type="text" id="member-id" name="member-id"><br>
            <button type="button" onclick="lookupMember()">Look up member</button>
            <div id="member-details" class="hidden">
                <h4>Member Details</h4>
                <p id="member-info"></p>
            </div>
            <h4>Claim Details</h4>
            <label for="last-day-worked">Last Day Worked:</label><br>
            <input type="date" id="last-day-worked" name="last-day-worked"><br>
            <label for="first-day-absent">First Day Absent:</label><br>
            <input type="date" id="first-day-absent" name="first-day-absent"><br>
            <label for="nature-of-absence">Nature of Absence:</label><br>
            <select id="nature-of-absence" name="nature-of-absence">
                <option value="illness">Illness</option>
                <option value="injury">Injury</option>
                <option value="other">Other</option>
            </select><br>
            <label for="details">Details:</label><br>
            <textarea id="details" name="details"></textarea><br>
            <label for="documents">Upload Documents:</label><br>
            <input type="file" id="documents" name="documents" multiple><br>
            <ul id="file-list"></ul><br>
            <button type="button" onclick="submitClaim()">Submit</button>
        </form>
        <div id="confirmation" class="hidden">
            <h3>Submission Confirmation</h3>
            <p>Reference Number: <span id="ref-number"></span></p>
            <p>Status: Received</p>
        </div>
    </div>
    <footer>MapleSure Insurance — fictional demo application</footer>
    <script>
        const mockData = {
            "12345": "Member Name: John Doe, Plan: Basic Health, Coverage: Active"
        };

        function lookupMember() {
            const policyNum = document.getElementById('policy-number').value;
            const memberInfo = document.getElementById('member-info');
            const memberDetails = document.getElementById('member-details');

            if (mockData[policyNum]) {
                memberInfo.textContent = mockData[policyNum];
                memberDetails.classList.remove('hidden');
            } else {
                memberInfo.textContent = "Member not found.";
                memberDetails.classList.remove('hidden');
            }
        }

        function submitClaim() {
            document.getElementById('claim-form').classList.add('hidden');
            document.getElementById('confirmation').classList.remove('hidden');
            const refNumber = "MS-2026-08-" + Math.floor(1000 + Math.random() * 9000);
            document.getElementById('ref-number').textContent = refNumber;
        }

        document.getElementById('documents').addEventListener('change', function() {
            const fileList = document.getElementById('file-list');
            fileList.innerHTML = '';
            Array.from(this.files).forEach(file => {
                const li = document.createElement('li');
                li.textContent = file.name;
                fileList.appendChild(li);
            });
        });

        function requireSignIn(service) {
            if (!isSignedIn()) {
                alert('Please sign in to access ' + service);
                // Redirect to sign in page
                window.location.href = '/signin.html';
            }
        }

        function isSignedIn() {
            // Mock sign-in check
            return false;
        }
    </script>
</body>
</html>

Acceptance criteria:
- US-3-AC1: Given an advisor on the landing page, when viewing tiles, then they see quick-links to policy lookup, claim status, and commission statement.
- US-3-AC2: Given an unsigned advisor, when clicking a tile, then they are redirected to the secure sign-in page.

Write pytest tests (a single test_app.py) that verify the happy path
STRUCTURALLY against the actual file above — read index.html from
Path(__file__).parent and assert what the criteria need: the form and its
required field ids exist, the upload input allows multiple files, the
confirmation panel and status markup exist, the member lookup mock data is
present. 4 to 6 focused tests, stdlib + pytest only, no browser, no server,
no network. Every assertion must hold for the file exactly as shown above,
and must be independent of the current date, time, or environment — never
hard-code a year, month, or timestamp; where the page generates a value at
runtime, assert the generating code exists, not the value it would produce
today.

JSON schema: {"files": [{"path": "test_app.py", "content": str}]}
